class TestPropertyBased:
    """Hypothesis-driven validation of scanner invariants."""

    @given(
        st.lists(st.integers(min_value=1, max_value=65535), max_size=20),
        st.booleans()
    )
    @settings(max_examples=50)
    @pytest.mark.asyncio
    async def test_finding_count_matches_open_ports(
        self, ports: List[int], all_open: bool
    ):
        """Number of findings must equal number of open ports."""
        plugin = PortScannerPlugin(config={"ports": ports})
        
        with patch.object(PortScannerPlugin, "_check_port", new_callable=AsyncMock) as mock_check:
            mock_check.return_value = all_open
            
            findings = await plugin.run("192.168.1.1")
            
            expected_count = len(ports) if all_open else 0
            assert len(findings) == expected_count

    @given(
        st.lists(st.integers(min_value=1, max_value=65535), max_size=10),
        st.integers(min_value=1, max_value=65535)
    )
    @settings(max_examples=50)
    @pytest.mark.asyncio
    async def test_finding_evidence_contains_target_and_port(
        self, ports: List[int], target_port: int
    ):
        """Evidence field must always contain target and port."""
        plugin = PortScannerPlugin(config={"ports": [target_port]})
        
        with patch.object(PortScannerPlugin, "_check_port", new_callable=AsyncMock) as mock_check:
            mock_check.return_value = True
            
            findings = await plugin.run("192.168.1.1")
            
            if findings:
                assert f"192.168.1.1:{target_port}" in findings[0].evidence

    @given(st.integers(min_value=1, max_value=65535))
    @settings(max_examples=50)
    @pytest.mark.asyncio
    async def test_single_port_scan_consistency(self, port: int):
        """Single port scan must produce deterministic results."""
        plugin = PortScannerPlugin(config={"ports": [port]})
        
        with patch.object(PortScannerPlugin, "_check_port", new_callable=AsyncMock) as mock_check:
            mock_check.return_value = True
            
            findings = await plugin.run("192.168.1.1")
            
            assert len(findings) == 1
            assert findings[0].title == f"Open Port Detected: {port}"
            assert findings[0].severity == Severity.INFO


